import{_ as n,l as r,o as a,c as t,v as i,p as o,x as l,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"mq-deadline 与 BFQ","description":"","frontmatter":{"title":"mq-deadline 与 BFQ","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/blk-schedulers.md","filePath":"cs/blk-schedulers.md","lastUpdated":1789023840000}'),h={name:"cs/blk-schedulers.md"};function m(B,e,u,F,b,q){const d=r("Mermaid");return a(),t("div",null,[e[1]||(e[1]=i('<h1 id="mq-deadline-与-bfq" tabindex="-1">mq-deadline 与 BFQ <a class="header-anchor" href="#mq-deadline-与-bfq" aria-label="Permalink to &quot;mq-deadline 与 BFQ&quot;">​</a></h1><div class="epigraph"><p>块层调度器把已提交的 bio 重新排序或分时：deadline 防饥饿，BFQ 按权重摊带宽，多队列时代默认常常是 none 或 mq-deadline。</p><footer>—— 据 Axboe 对 Linux 块层的设计；Valente 等对 BFQ 的论述；McKusick 对磁盘臂调度的背景</footer></div><p><a href="/cs/sendfile-splice">上一课</a>把页送进 I/O 路径。请求还要变成对设备的队列。<a href="/cs/disk-sched">磁盘调度</a> 主干给过电梯直觉。缺口是 <strong>Linux 多队列调度器</strong>：blk-mq 上的 mq-deadline 与 BFQ，以及为何 NVMe 上常关掉调度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HDD 上随机写很贵，CFQ/BFQ 把进程带宽当公平对象。NVMe 多队列、延迟以十微秒计，软件再排序可能净亏损。mq-deadline：读写分开 FIFO，给读一个期限以免被写饿死。BFQ：按 cgroup/进程权重分配时间片，适合桌面与共享 HDD。none：硬件队列即调度。缺口不是再讲柱面，而是：请求在 blk-mq 软件队列与硬件队列之间如何被选走。</p><p><span class="marginnote">单队列时代的 CFQ 已退。kyber 是延迟目标另一选择。本课以 deadline 与 BFQ 对照「期限 vs 公平」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>FS 提交 bio → 请求 → 某 hctx 的调度器。mq-deadline 维护读/写 FIFO 与按扇区排序树，到期则派读。BFQ 维护每队列 vtime，选最小者，空闲时 idling 等待同步。完成 IRQ 后可再派下一个。对照 <a href="/cs/readahead">预读</a>：大顺序请求让任何调度器都轻松。对照 <a href="/cs/direct-io">O_DIRECT</a>：请求尺寸由应用决定。</p>',8)),(a(),o(p,null,{default:l(()=>[c(d,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIO%5B%22bio%22%5D%20--%3E%20MQ%5B%22blk-mq%20%E8%BD%AF%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20MQ%20--%3E%20DL%5B%22mq-deadline%20%E6%9C%9F%E9%99%90%22%5D%0A%20%20MQ%20--%3E%20BFQ%5B%22BFQ%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20MQ%20--%3E%20NONE%5B%22none%20%E7%9B%B4%E9%80%9A%22%5D%0A%20%20DL%20--%3E%20HW%5B%22%E7%A1%AC%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20BFQ%20--%3E%20HW%0A%20%20NONE%20--%3E%20HW%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调度器把「谁先用设备」从 FS 里抽出来，使同一块设备可被公平或低延迟策略分享。闪存上这条税常不值得，于是默认 none。不要把 BFQ 写成 CFS：对象是请求与带宽，不是 CPU vruntime，虽然公平份额直觉同源。</p><p>与 <a href="/cs/cgroups">cgroup</a>：blkio/io 控制器给 BFQ 权重或限制 IOPS，后课 blkio 再钉。</p><p>实现上：blk-mq 的软件队列按 hctx 分，调度器状态也是每队列一份，不再有全局电梯锁。NVMe 默认 none 后，io.weight 一类公平只能靠 BFQ 或 cgroup 节流，而不是硬件自己懂权重。 读法上只引用<a href="/cs/sendfile-splice">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>mq-deadline 与 BFQ</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每个调参 sysfs 文件。不保证 virtio-blk 上的最佳选择。下一课看设备端真正的多队列：NVMe 驱动。</p><p>版本字段会变，课序钉的是机制对象「mq-deadline 与 BFQ」，不是某一主线内核的结构体名。 后课默认：块层可以排序或直通。NVMe 提交/完成队列如何接驱动，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>mq-deadline 用期限防读饥饿；BFQ 摊带宽；NVMe 常 none。</li><li>blk-mq 把请求送到每核硬件队列。</li><li>NVMe 驱动是下一课。</li><li>出处：Linux 块层文档；Valente BFQ；Axboe；<em>OSTEP</em>。</li></ul>',11))])}const E=n(h,[["render",m]]);export{f as __pageData,E as default};
